/**
 * #{#pdf1a} Detect whether a receipt file path is a PDF.
 *
 * @param path - The receipt_image_path from the receipts table
 * @returns true if the file extension is .pdf (case-insensitive)
 */
export function isPdfFile(path: string | null | undefined): boolean {
	if (!path) return false;
	return path.toLowerCase().endsWith('.pdf');
}

