/**
 * Typesets an email body into the SVG that is an emailed receipt's only visual
 * artifact.
 *
 * This has nothing to do with OCR: it does not call Mistral, does not need the
 * API key, and does not know what extraction is. `processEmailText` reads the
 * raw email text, so the picture is purely for a human — which is what makes it
 * free to change.
 *
 * Wrapping has to happen *here*, in Deno, before the `<tspan>`s are emitted. An
 * SVG loaded through `<img src>` renders in restricted mode, where Chrome and
 * Safari do not render HTML inside `<foreignObject>`, so the browser cannot be
 * asked to do the line breaking.
 *
 * This module is checked by BOTH checkers — `deno check` covers
 * `supabase/functions/`, and `tsc` pulls it in transitively once a script under
 * `scripts/` imports it. So it must contain no `Deno` globals and must use
 * explicit `.ts` import specifiers.
 */

/**
 * Stamped on the SVG root. The backfill reads it to make a second run a no-op,
 * so bump it whenever a change in here would produce a different picture from
 * the same input text.
 */
export const RENDER_VERSION = 2;

/** Attribute carrying {@link RENDER_VERSION} on the `<svg>` element. */
export const RENDER_VERSION_ATTRIBUTE = 'data-yfl-render-version';

/**
 * Page geometry. 1100px rather than the original 800px because wrapping
 * *increases* height, and a taller, narrower document is smaller once the viewer
 * fits it — so buying columns back with width is the cheaper trade.
 */
const SVG_WIDTH = 1100;
const FONT_SIZE = 14;
const LINE_HEIGHT = 20;
const PADDING = 20;

/**
 * In a monospace font every glyph advances by a fixed fraction of the em. 0.6 is
 * the usual value and is deliberately a slight over-estimate of the narrower
 * faces, so the computed column errs towards wrapping early rather than
 * clipping.
 */
const MONOSPACE_ADVANCE_RATIO = 0.6;

/** Tabs are expanded to a fixed run of spaces, not to real tab stops. */
const TAB_WIDTH = 4;

/**
 * How many characters fit on a line — *computed* from the width and the font
 * metrics rather than hardcoded beside them, so the three numbers above can
 * never drift out of agreement with it.
 */
export const WRAP_COLUMNS = Math.floor(
	(SVG_WIDTH - PADDING * 2) / (FONT_SIZE * MONOSPACE_ADVANCE_RATIO)
);

/** Closing tags that end a visual block and therefore imply a line break. */
const BLOCK_CLOSE_TAGS = [
	'p',
	'div',
	'tr',
	'li',
	'ul',
	'ol',
	'table',
	'blockquote',
	'h1',
	'h2',
	'h3',
	'h4',
	'h5',
	'h6'
];

const BLOCK_CLOSE_PATTERN = new RegExp(`</(?:${BLOCK_CLOSE_TAGS.join('|')})\\s*>`, 'gi');

/**
 * Reduce HTML markup to the text a person would have read.
 *
 * Applied to the **rendered text only**. Mistral keeps receiving exactly the
 * bytes it receives today, so extraction behaviour is provably unchanged by this
 * function existing.
 */
export function stripHtml(html: string): string {
	return (
		html
			// Contents, not just the tags — a <style> block's CSS is not text, and
			// dropping only the tags would paste the whole stylesheet into the picture.
			.replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, '')
			.replace(/<!--[\s\S]*?-->/g, '')
			// Structure that carries a line break, converted before the tags are
			// dropped. Without this a div-soup marketing email arrives as one
			// 40,000-character line and every wrap decision after it is nonsense.
			.replace(/<br\s*\/?>/gi, '\n')
			.replace(BLOCK_CLOSE_PATTERN, '\n')
			// Cells sit side by side: they need a separator, not a break.
			.replace(/<\/t[dh]\s*>/gi, ' ')
			.replace(/<[^>]+>/g, '')
			.replace(/&nbsp;/gi, ' ')
			.replace(/&lt;/gi, '<')
			.replace(/&gt;/gi, '>')
			.replace(/&quot;/gi, '"')
			.replace(/&#0*39;/g, "'")
			.replace(/&apos;/gi, "'")
			// Last, so `&amp;lt;` decodes to the literal `&lt;` rather than to `<`.
			.replace(/&amp;/gi, '&')
	);
}

/**
 * Break one logical line into rendered lines of at most `columns` characters.
 *
 * Word wrap alone is not enough: a 200-character tracking URL contains no space
 * to break at, and leaving it whole would let the outermost `<svg>` clip it
 * exactly as before. So a token wider than the column is broken mid-word.
 */
function wrapLine(line: string, columns: number): string[] {
	if (line.length <= columns) return [line];

	const wrapped: string[] = [];
	let rest = line;

	while (rest.length > columns) {
		let breakAt = rest.lastIndexOf(' ', columns);
		// No usable space in range means the token itself is over-wide (or the line
		// is indented past the column): break on the column and keep going.
		if (breakAt < 1 || rest.slice(0, breakAt).trim() === '') breakAt = columns;
		wrapped.push(rest.slice(0, breakAt).trimEnd());
		rest = rest.slice(breakAt).replace(/^ +/, '');
	}
	if (rest.length > 0) wrapped.push(rest);

	return wrapped;
}

/**
 * Collapse runs of blank lines to one, and drop them at the ends entirely.
 * Forwarded mail carries long blank stretches that otherwise inflate the SVG's
 * height — the white space filling the bottom half of a reported screenshot.
 */
function collapseBlankRuns(lines: string[]): string[] {
	const kept: string[] = [];
	let blankRun = 0;

	for (const line of lines) {
		if (line === '') {
			blankRun += 1;
			if (blankRun === 1) kept.push('');
		} else {
			blankRun = 0;
			kept.push(line);
		}
	}

	while (kept.length > 0 && kept[0] === '') kept.shift();
	while (kept.length > 0 && kept[kept.length - 1] === '') kept.pop();

	return kept;
}

/**
 * The lines that will be drawn, in order: normalise newlines, expand tabs,
 * collapse blank runs, then wrap. Collapsing before wrapping is deliberate —
 * wrapping never produces a blank line, so the other order would only do more
 * work.
 */
export function layoutText(text: string, columns: number = WRAP_COLUMNS): string[] {
	const normalized = text
		.replace(/\r\n?/g, '\n')
		.split('\n')
		.map((line) => line.replace(/\t/g, ' '.repeat(TAB_WIDTH)).trimEnd());

	return collapseBlankRuns(normalized).flatMap((line) => wrapLine(line, columns));
}

/** Render already-plain text (see {@link stripHtml}) as an SVG document. */
export function renderTextToSvg(text: string): string {
	const lines = layoutText(text);
	const drawn = lines.length > 0 ? lines : [''];
	const height = drawn.length * LINE_HEIGHT + PADDING * 2;

	// `xml:space="preserve"` keeps leading indentation and column alignment, which
	// SVG collapses by default. The consequence is that the <tspan>s must be
	// joined with NO separator: any whitespace between them would now be rendered.
	const tspans = drawn
		.map(
			(line, i) =>
				`<tspan x="${PADDING}" dy="${i === 0 ? 0 : LINE_HEIGHT}">${escapeXml(line)}</tspan>`
		)
		.join('');

	return `<?xml version="1.0" encoding="UTF-8"?>
<svg width="${SVG_WIDTH}" height="${height}" xmlns="http://www.w3.org/2000/svg" ${RENDER_VERSION_ATTRIBUTE}="${RENDER_VERSION}">
  <rect width="100%" height="100%" fill="white"/>
  <text x="${PADDING}" y="${PADDING + FONT_SIZE}" font-family="monospace" font-size="${FONT_SIZE}" fill="black" xml:space="preserve">${tspans}</text>
</svg>`;
}

/** {@link renderTextToSvg} as the UTF-8 bytes the storage upload wants. */
export function renderTextToSvgBytes(text: string): Uint8Array {
	return new TextEncoder().encode(renderTextToSvg(text));
}

function escapeXml(unsafe: string): string {
	return unsafe
		.replace(/&/g, '&amp;')
		.replace(/</g, '&lt;')
		.replace(/>/g, '&gt;')
		.replace(/"/g, '&quot;')
		.replace(/'/g, '&apos;');
}

