import { describe, it, expect } from 'vitest';
import {
	RENDER_VERSION,
	RENDER_VERSION_ATTRIBUTE,
	WRAP_COLUMNS,
	layoutText,
	renderTextToSvg,
	renderTextToSvgBytes,
	stripHtml
} from './textRender.ts';

describe('WRAP_COLUMNS', () => {
	it('is computed from the geometry, not hardcoded', () => {
		expect(WRAP_COLUMNS).toBe(Math.floor((1100 - 40) / (14 * 0.6)));
	});
});

describe('layoutText', () => {
	it('leaves a line that already fits', () => {
		expect(layoutText('Total: $42.00')).toEqual(['Total: $42.00']);
	});

	it('wraps on whitespace at the computed column', () => {
		const words = 'lorem '.repeat(60).trim();
		const lines = layoutText(words);

		expect(lines.length).toBeGreaterThan(1);
		for (const line of lines) expect(line.length).toBeLessThanOrEqual(WRAP_COLUMNS);
		expect(lines.join(' ')).toBe(words);
	});

	it('breaks an unbreakable token mid-word', () => {
		const url = `https://track.example.com/${'a'.repeat(200)}`;
		const lines = layoutText(url);

		expect(lines.length).toBeGreaterThan(1);
		for (const line of lines) expect(line.length).toBeLessThanOrEqual(WRAP_COLUMNS);
		expect(lines.join('')).toBe(url);
	});

	it('collapses runs of blank lines to one', () => {
		expect(layoutText('a\n\n\n\n\nb')).toEqual(['a', '', 'b']);
	});

	it('drops leading and trailing blank lines', () => {
		expect(layoutText('\n\n  \nreceipt\n\n \n\n')).toEqual(['receipt']);
	});

	it('normalises CRLF', () => {
		expect(layoutText('a\r\nb\rc')).toEqual(['a', 'b', 'c']);
	});

	it('expands tabs so the column count is honest', () => {
		expect(layoutText('a\tb')).toEqual(['a    b']);
	});

	it('respects an explicit column override', () => {
		expect(layoutText('one two three', 7)).toEqual(['one two', 'three']);
	});
});

describe('stripHtml', () => {
	it('drops script and style contents, not just their tags', () => {
		const html = '<style>.x{color:red}</style><p>Total $9</p><script>alert(1)</script>';
		const text = stripHtml(html);

		expect(text).not.toContain('color:red');
		expect(text).not.toContain('alert');
		expect(text).toContain('Total $9');
	});

	it('drops HTML comments', () => {
		expect(stripHtml('<!--[if mso]>junk<![endif]-->kept')).toBe('kept');
	});

	it('turns br, /p and /tr into newlines', () => {
		expect(layoutText(stripHtml('a<br>b</p>c</tr>d'))).toEqual(['a', 'b', 'c', 'd']);
	});

	it('separates table cells without breaking the row', () => {
		expect(layoutText(stripHtml('<tr><td>Tax</td><td>$1.20</td></tr>'))).toEqual(['Tax $1.20']);
	});

	it('decodes the common entities', () => {
		expect(stripHtml('Ben &amp; Jerry&#39;s &lt;tag&gt; &quot;x&quot;&nbsp;y')).toBe(
			'Ben & Jerry\'s <tag> "x" y'
		);
	});

	it('decodes &amp; last so a double-escaped entity survives', () => {
		expect(stripHtml('&amp;lt;')).toBe('&lt;');
	});
});

describe('renderTextToSvg', () => {
	it('emits the version marker', () => {
		expect(renderTextToSvg('x')).toContain(`${RENDER_VERSION_ATTRIBUTE}="${RENDER_VERSION}"`);
	});

	it('is 1100px wide with a height that follows the line count', () => {
		const svg = renderTextToSvg('a\nb\nc');

		expect(svg).toContain('width="1100"');
		expect(svg).toContain(`height="${3 * 20 + 40}"`);
	});

	it('escapes XML after stripping', () => {
		const svg = renderTextToSvg(stripHtml('<p>Ben &amp; Jerry&#39;s</p>'));

		expect(svg).toContain('Ben &amp; Jerry&apos;s');
		expect(svg).not.toContain("Jerry's");
	});

	it('preserves whitespace and joins tspans with no separator', () => {
		const svg = renderTextToSvg('  indented');

		expect(svg).toContain('xml:space="preserve"');
		expect(svg).toContain('>  indented</tspan>');
		expect(svg).not.toContain('</tspan>\n');
	});

	it('advances every line after the first by one line height', () => {
		const svg = renderTextToSvg('a\nb');

		expect(svg).toContain('dy="0"');
		expect(svg).toContain('dy="20"');
	});

	it('renders empty input as a valid one-line document', () => {
		const svg = renderTextToSvg('');

		expect(svg).toContain('<tspan x="20" dy="0"></tspan>');
		expect(svg).toContain(`height="${20 + 40}"`);
	});

	it('bytes decode back to the document', () => {
		const text = 'Merchant\nTotal $9.99';
		expect(new TextDecoder().decode(renderTextToSvgBytes(text))).toBe(renderTextToSvg(text));
	});
});

