// Deno Deploy / Supabase Edge Function for Resend webhook.
//
// This file is the imperative SHELL: it wires the real runtime collaborators
// (Supabase service client, global fetch, Deno.env, the clock, Mistral OCR,
// the Bank of Canada rate lookup, and svix signature verification) into the
// injectable core `handleResendWebhook` in `handler.ts`. All request→response
// orchestration and branching lives in the core, where it is unit-tested under
// vitest. The only untested lines here are the dependency constructors and the
// one-line `Deno.serve` binding — deliberately trivial, matching the repo's
// "seam-only" testing philosophy.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { Webhook } from 'https://esm.sh/svix@1.15.0';
import { handleResendWebhook, type OcrPort } from './handler.ts';
import { ocrFromUrl, processEmailText, textToImage } from '../_shared/mistral.ts';
import { fetchExchangeRate } from '../_shared/exchangeRate.ts';

/** Service-role client used to bypass RLS for webhook-driven inserts. */
function createServiceClient(url: string, key: string) {
	return createClient(url, key, {
		auth: { autoRefreshToken: false, persistSession: false }
	});
}

/**
 * Verifies the Resend webhook signature using the Svix library.
 * Based on: https://resend.com/docs/dashboard/webhooks/verify-webhooks-requests
 * Kept in the shell so the svix dependency never has to load under vitest.
 */
function verifyWebhookSignature(headers: Headers, payload: string, signingSecret: string): boolean {
	const svixId = headers.get('svix-id');
	const svixTimestamp = headers.get('svix-timestamp');
	const svixSignature = headers.get('svix-signature');

	console.log('Signature verification headers:', {
		hasSignature: !!svixSignature,
		hasTimestamp: !!svixTimestamp,
		hasId: !!svixId
	});

	if (!svixId || !svixTimestamp || !svixSignature) {
		console.error('Missing webhook signature headers:', {
			signature: svixSignature ? 'present' : 'missing',
			timestamp: svixTimestamp ? 'present' : 'missing',
			id: svixId ? 'present' : 'missing'
		});
		return false;
	}

	try {
		const wh = new Webhook(signingSecret);

		// Verify the webhook - this will throw on error
		wh.verify(payload, {
			'svix-id': svixId,
			'svix-timestamp': svixTimestamp,
			'svix-signature': svixSignature
		});

		console.log('Webhook signature verified successfully');
		return true;
	} catch (err) {
		console.error('Webhook signature verification failed:', err);
		return false;
	}
}

const denoEnv = (key: string): string | undefined => Deno.env.get(key);

/** Real OCR collaborator — Mistral vision, with the injected fetch/env seam wired. */
const realOcr: OcrPort = {
	processEmailText: (text) => processEmailText(text, { fetchFn: fetch, env: denoEnv }),
	textToImage: (text) => textToImage(text),
	ocrFromUrl: (fileUrl, mimeType) => ocrFromUrl(fileUrl, mimeType, { fetchFn: fetch, env: denoEnv })
};

Deno.serve((req) =>
	handleResendWebhook(req, {
		supabase: createServiceClient(
			Deno.env.get('SUPABASE_URL') ?? '',
			Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
		),
		fetchFn: fetch,
		env: denoEnv,
		now: () => new Date(),
		ocr: realOcr,
		exchangeRate: (currency, date) => fetchExchangeRate(currency, date, fetch),
		verifySignature: verifyWebhookSignature
	})
);

