/**
 * Zoom limits for the receipt viewer. 100% means fit-to-width; the ceiling is a
 * property of the individual image. See the "Zoom never invents pixels"
 * invariant in `docs/domain-model.md` and ADR 0007.
 */

export interface FitDimensions {
	width: number;
	height: number;
}

/** The floor, and the meaning of "fit to width". */
export const MIN_ZOOM = 100;

/** The +/- buttons and keyboard snap to multiples of this. Wheel zoom does not. */
export const ZOOM_STEP = 50;

export const DOUBLE_TAP_ZOOM = 200;

/**
 * The share of the window width the receipt fills at 100%. This is what "100%"
 * means, so the fit arithmetic and the CSS box both derive from it. The vertical
 * bound is presentational only — a `max-h-[80vh]` class, like the PDF branch.
 */
export const VIEWPORT_WIDTH_FRACTION = 0.9;

/**
 * A vector image has no pixel grid to exhaust, so its ceiling is arbitrary. It
 * exists so the zoom-in button can honestly disable itself and a stray gesture
 * cannot ask the browser to lay out a 40,000px element.
 */
export const VECTOR_MAX_ZOOM = 800;

/**
 * The size an image occupies at 100%: scaled to the viewport width, never scaled
 * up. A tall receipt overflows and scrolls rather than shrinking to fit — at
 * fit-to-box it was visible but not readable, and reading is what the viewer is
 * for.
 */
export function calculateFitDimensions(
	naturalWidth: number,
	naturalHeight: number,
	viewportWidth: number
): FitDimensions {
	const scale = Math.min(viewportWidth / naturalWidth, 1);
	return { width: naturalWidth * scale, height: naturalHeight * scale };
}

/**
 * The zoom at which a raster image is displayed at its true resolution. Returns
 * MIN_ZOOM when it is already there, which is what disables the controls.
 */
export function calculateMaxZoom(naturalWidth: number, baseWidth: number): number {
	if (baseWidth <= 0) return MIN_ZOOM;
	return Math.max(MIN_ZOOM, (naturalWidth / baseWidth) * MIN_ZOOM);
}

