function handleImageLoad(e: Event) {
	const img = e.target as HTMLImageElement;
	naturalWidth = img.naturalWidth;
	const fit = calculateFitDimensions(
		img.naturalWidth,
		img.naturalHeight,
		window.innerWidth * VIEWPORT_FRACTION.width,
		window.innerHeight * VIEWPORT_FRACTION.height
	);
	baseWidth = fit.width;
	baseHeight = fit.height;
}

