/**
 * #{#zom1b} #{#pdf1c} Ctrl/Cmd + wheel zooms toward the cursor; a plain wheel
 * falls through so the container scrolls natively. macOS synthesizes
 * `ctrlKey` for a trackpad pinch, which is why that gesture works here.
 */
function handleWheel(e: WheelEvent) {
	if (isPdf) return; // #{#pdf1c} Let browser PDF viewer handle scroll
	if (!e.ctrlKey && !e.metaKey) return;
	e.preventDefault();
	const delta = e.deltaMode === 1 ? e.deltaY * LINE_HEIGHT_PX : e.deltaY;
	zoomTo(zoom * Math.exp(-delta * WHEEL_ZOOM_SENSITIVITY), e.clientX, e.clientY);
}

