import { describe, it, expect, vi } from 'vitest';
import { render } from 'vitest-browser-svelte';
import ReceiptImageViewer from './ReceiptImageViewer.svelte';
import { VIEWPORT_FRACTION } from '$lib/utils/imageZoom';

/**
 * Behaviour tests for the real <ReceiptImageViewer> zoom controls.
 *
 * The previous spec was hollow: every `it()` re-declared the zoom arithmetic
 * inline (`let zoom = 100; zoom += 50; expect(zoom).toBe(150)`) and asserted
 * against its own copy — 859 lines that passed no matter what the component did
 * (its header even admitted it was stale TDD RED-phase scaffolding). These render
 * the actual component and drive its buttons/keyboard, asserting the visible
 * zoom %, the disabled boundaries, and close wiring.
 *
 * The zoom ceiling is derived from each image's own resolution ("zoom never
 * invents pixels" — see the domain model), so these use SVG data URLs of a known
 * natural size rather than a URL that never loads. The arithmetic itself is
 * covered in `$lib/utils/imageZoom.spec.ts`; what matters here is the resulting
 * button state and that the image is never painted larger than it really is.
 *
 * Pointer gestures (wheel-zoom, drag-pan, pinch) stay a manual-verify item — they
 * use imperative `{ passive: false }` listeners that unit tests can't faithfully
 * drive (tracked in the backlog). The button + keyboard path is the deterministic,
 * render-testable surface, and it's where the real clamp/snap logic lives.
 */

/** A loadable image of an exact natural size, with no network. */
function imageUrl(width: number, height: number): string {
	const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}"><rect width="100%" height="100%" fill="#ccc"/></svg>`;
	return `data:image/svg+xml;base64,${btoa(svg)}`;
}

/** Bigger than any test viewport, so there is real headroom to zoom into. */
const LARGE = imageUrl(4000, 6000);

/** Smaller than any test viewport, so it is already at native size at 100%. */
const SMALL = imageUrl(80, 60);

const props = { imageUrl: LARGE, show: true };

/**
 * The <img> the viewer renders, once the browser has decoded it and the load
 * handler has sized it. The element is re-queried on each poll: the viewer swaps
 * the placeholder <img> for an explicitly-sized one once dimensions are known.
 */
async function loadedImage(screen: ReturnType<typeof render>): Promise<HTMLImageElement> {
	return vi.waitUntil(() => {
		const img = screen.container.querySelector('img');
		return img?.style.width ? (img as HTMLImageElement) : false;
	});
}

describe('ReceiptImageViewer', () => {
	it('renders nothing until show is true', async () => {
		const screen = render(ReceiptImageViewer, { imageUrl: LARGE, show: false });
		await expect.element(screen.getByRole('dialog')).not.toBeInTheDocument();
	});

	it('clips the receipt to the same box the fit arithmetic uses', async () => {
		// VIEWPORT_FRACTION exists so the CSS box and the fit calculation cannot
		// drift; if they do, 100% stops meaning "fit to viewport" and the whole
		// 1:1 ceiling is computed against the wrong denominator.
		const screen = render(ReceiptImageViewer, { ...props });
		const img = await loadedImage(screen);
		const container = img.parentElement as HTMLElement;

		expect(container.style.maxWidth).toBe(`${VIEWPORT_FRACTION.width * 100}vw`);
		expect(container.style.maxHeight).toBe(`${VIEWPORT_FRACTION.height * 100}vh`);
		expect(parseFloat(img.style.height)).toBeLessThanOrEqual(
			window.innerHeight * VIEWPORT_FRACTION.height + 1
		);
	});

	it('opens at 100% with zoom-out disabled and zoom-in enabled', async () => {
		const screen = render(ReceiptImageViewer, { ...props });

		await expect.element(screen.getByRole('dialog')).toBeVisible();
		await expect.element(screen.getByText('100%', { exact: true })).toBeVisible();
		await expect.element(screen.getByRole('button', { name: 'Zoom out' })).toBeDisabled();
		await expect.element(screen.getByRole('button', { name: 'Zoom in' })).toBeEnabled();
	});

	it('steps up by 50% on each Zoom in click', async () => {
		const screen = render(ReceiptImageViewer, { ...props });
		await loadedImage(screen);

		await screen.getByRole('button', { name: 'Zoom in' }).click();
		await expect.element(screen.getByText('150%', { exact: true })).toBeVisible();

		await screen.getByRole('button', { name: 'Zoom in' }).click();
		await expect.element(screen.getByText('200%', { exact: true })).toBeVisible();
	});

	it('stops zooming at the image’s own resolution and never paints it larger', async () => {
		const screen = render(ReceiptImageViewer, { ...props });
		const img = await loadedImage(screen);
		const zoomIn = screen.getByRole('button', { name: 'Zoom in' });

		// Climb until the control turns itself off; the ceiling depends on the
		// viewport, so press rather than assume a number.
		for (let i = 0; i < 40 && !(await zoomIn.query())?.hasAttribute('disabled'); i++) {
			await zoomIn.click();
		}

		await expect.element(zoomIn).toBeDisabled();
		// 1:1 — the whole point. Every pixel on screen is now a real pixel.
		expect(Math.round(parseFloat(img.style.width))).toBe(img.naturalWidth);
	});

	it('offers no zoom at all for an image already smaller than the viewport', async () => {
		const screen = render(ReceiptImageViewer, { imageUrl: SMALL, show: true });
		await loadedImage(screen);

		// There are no further real pixels, so the control says so rather than
		// magnifying interpolation.
		await expect.element(screen.getByRole('button', { name: 'Zoom in' })).toBeDisabled();
		await expect.element(screen.getByRole('button', { name: 'Zoom out' })).toBeDisabled();
		await expect.element(screen.getByText('100%', { exact: true })).toBeVisible();
	});

	it('steps back down on Zoom out', async () => {
		const screen = render(ReceiptImageViewer, { ...props });
		await loadedImage(screen);

		await screen.getByRole('button', { name: 'Zoom in' }).click(); // 150
		await screen.getByRole('button', { name: 'Zoom in' }).click(); // 200
		await screen.getByRole('button', { name: 'Zoom out' }).click(); // 150
		await expect.element(screen.getByText('150%', { exact: true })).toBeVisible();
	});

	it('Reset returns to 100%', async () => {
		const screen = render(ReceiptImageViewer, { ...props });
		await loadedImage(screen);

		await screen.getByRole('button', { name: 'Zoom in' }).click(); // 150
		await screen.getByRole('button', { name: 'Zoom in' }).click(); // 200
		await screen.getByRole('button', { name: 'Reset zoom to 100%' }).click();
		await expect.element(screen.getByText('100%', { exact: true })).toBeVisible();
	});

	it('supports keyboard zoom shortcuts (+ / - / 0)', async () => {
		const screen = render(ReceiptImageViewer, { ...props });
		await loadedImage(screen);

		window.dispatchEvent(new KeyboardEvent('keydown', { key: '+', bubbles: true }));
		await expect.element(screen.getByText('150%', { exact: true })).toBeVisible();

		window.dispatchEvent(new KeyboardEvent('keydown', { key: '-', bubbles: true }));
		await expect.element(screen.getByText('100%', { exact: true })).toBeVisible();

		window.dispatchEvent(new KeyboardEvent('keydown', { key: '+', bubbles: true }));
		window.dispatchEvent(new KeyboardEvent('keydown', { key: '0', bubbles: true }));
		await expect.element(screen.getByText('100%', { exact: true })).toBeVisible();
	});

	it('calls onclose from the close button and from Escape', async () => {
		const onclose = vi.fn();
		const screen = render(ReceiptImageViewer, { ...props, onclose });

		await screen.getByRole('button', { name: 'Close image viewer' }).click();
		expect(onclose).toHaveBeenCalledTimes(1);

		window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
		expect(onclose).toHaveBeenCalledTimes(2);
	});

	it('renders a PDF in an iframe with no zoom controls', async () => {
		const screen = render(ReceiptImageViewer, {
			imageUrl: 'http://localhost/receipt.pdf',
			show: true,
			isPdf: true,
			altText: 'Receipt PDF'
		});

		await expect.element(screen.getByTitle('Receipt PDF')).toBeVisible();
		await expect.element(screen.getByRole('button', { name: 'Zoom in' })).not.toBeInTheDocument();
	});
});

