it('gives a vector receipt room to zoom where a raster of the same size has none', async () => {
	const raster = render(ReceiptImageViewer, { imageUrl: TALL, show: true });
	await loadedImage(raster);
	await expect.element(raster.getByRole('button', { name: 'Zoom in' })).toBeDisabled();

	const vector = render(ReceiptImageViewer, { imageUrl: TALL, show: true, isVector: true });
	await loadedImage(vector);
	const zoomIn = vector.getByRole('button', { name: 'Zoom in' });

	await expect.element(zoomIn).toBeEnabled();
	for (let i = 0; i < 40 && !(await zoomIn.query())?.hasAttribute('disabled'); i++) {
		await zoomIn.click();
	}
	await expect
		.element(vector.getByText(`${VECTOR_MAX_ZOOM}%`, { exact: true }))
		.toBeVisible();
});

it('scrolls on a plain wheel and zooms only with a modifier', async () => {
	const screen = render(ReceiptImageViewer, { ...props });
	const img = await loadedImage(screen);
	const container = img.parentElement as HTMLElement;

	const plain = new WheelEvent('wheel', { deltaY: -120, cancelable: true, bubbles: true });
	container.dispatchEvent(plain);
	expect(plain.defaultPrevented).toBe(false);
	await expect.element(screen.getByText('100%', { exact: true })).toBeVisible();

	const pinched = new WheelEvent('wheel', {
		deltaY: -120,
		ctrlKey: true,
		cancelable: true,
		bubbles: true
	});
	container.dispatchEvent(pinched);
	expect(pinched.defaultPrevented).toBe(true);
	await expect.element(screen.getByText('100%', { exact: true })).not.toBeInTheDocument();
});

it('zooms the wheel continuously rather than in 50% steps', async () => {
	const screen = render(ReceiptImageViewer, { ...props });
	const img = await loadedImage(screen);
	const container = img.parentElement as HTMLElement;

