/**
 * One-shot backfill: re-render every emailed-receipt SVG with the current
 * renderer. Delete this file once it has been run — see
 * docs/plans/2026-08-03-emailed-receipt-legibility-design.md.
 *
 *   npm run backfill:email-svgs           # dry run, prints what would change
 *   npm run backfill:email-svgs -- --apply
 *
 * Storage objects are overwritten in place. There are NO database writes, so
 * `receipt_image_path` never moves and the worst case is a bad picture — which is
 * reconstructible from the text inside it.
 */
import { createClient, type SupabaseClient } from '@supabase/supabase-js';
import {
	RENDER_VERSION,
	RENDER_VERSION_ATTRIBUTE,
	renderTextToSvg,
	stripHtml
} from '../supabase/functions/_shared/textRender.ts';

const BUCKET = 'receipts';
const PAGE_SIZE = 500;

function readConfig(): { url: string; serviceRoleKey: string } {
	const url = process.env.PUBLIC_SUPABASE_URL;
	const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

	const missing: string[] = [];
	if (!url) missing.push('PUBLIC_SUPABASE_URL');
	if (!serviceRoleKey) missing.push('SUPABASE_SERVICE_ROLE_KEY');
	if (missing.length > 0) {
		throw new Error(
			`Missing required env var(s): ${missing.join(', ')}.\n` +
				'Run through 1Password:  npm run backfill:email-svgs'
		);
	}

	return { url: url!, serviceRoleKey: serviceRoleKey! };
}

/** Every `.svg` receipt path; only `renderTextToSvg` produces those. */
async function listCandidatePaths(admin: SupabaseClient): Promise<string[]> {
	const paths: string[] = [];
	for (let from = 0; ; from += PAGE_SIZE) {
		const { data, error } = await admin
			.from('receipts')
			.select('receipt_image_path')
			.like('receipt_image_path', '%.svg')
			.order('receipt_image_path')
			.range(from, from + PAGE_SIZE - 1);
		if (error) throw new Error(`select receipts failed: ${error.message}`);
		if (!data || data.length === 0) break;

		for (const row of data) {
			if (row.receipt_image_path) paths.push(row.receipt_image_path as string);
		}
		if (data.length < PAGE_SIZE) break;
	}
	return paths;
}

function svgRenderVersion(svg: string): number {
	const match = svg.match(new RegExp(`${RENDER_VERSION_ATTRIBUTE}="(\\d+)"`));
	return match ? Number(match[1]) : 0;
}

function unescapeXml(text: string): string {
	return text
		.replace(/&lt;/g, '<')
		.replace(/&gt;/g, '>')
		.replace(/&quot;/g, '"')
		.replace(/&apos;/g, "'")
		.replace(/&amp;/g, '&');
}

/**
 * Recover the source text. The clipping was only ever a rendering effect — every
 * line sits in full inside its `<tspan>` — which is what makes this lossless.
 */
function recoverText(svg: string): string {
	const lines: string[] = [];
	for (const match of svg.matchAll(/<tspan\b[^>]*>([\s\S]*?)<\/tspan>/g)) {
		lines.push(unescapeXml(match[1]));
	}
	return lines.join('\n');
}

/**
 * Old SVGs were rendered from `email.text || email.html` with no stripping, so an
 * HTML-only email's picture is full of markup. Which branch produced a given file
 * is not recorded, but a plain-text email does not contain `<table style=...>`.
 */
function looksLikeHtml(text: string): boolean {
	return /<(?:p|div|table|tbody|tr|td|br|span|a|img|html|body|style)\b[^>]*>/i.test(text);
}

async function main() {
	const apply = process.argv.includes('--apply');
	const { url, serviceRoleKey } = readConfig();
	const admin = createClient(url, serviceRoleKey, {
		auth: { autoRefreshToken: false, persistSession: false }
	});

	console.log(`Target: ${new URL(url).host}`);
	console.log(apply ? 'Mode:   APPLY (objects will be overwritten)' : 'Mode:   dry run');

	const paths = await listCandidatePaths(admin);
	console.log(`Found ${paths.length} .svg receipt${paths.length === 1 ? '' : 's'}\n`);

	let rerendered = 0;
	let skipped = 0;
	let failed = 0;

	for (const path of paths) {
		const { data, error } = await admin.storage.from(BUCKET).download(path);
		if (error || !data) {
			console.error(`FAIL     ${path} — download: ${error?.message ?? 'no body'}`);
			failed += 1;
			continue;
		}

		const original = await data.text();
		if (svgRenderVersion(original) >= RENDER_VERSION) {
			skipped += 1;
			continue;
		}

		const recovered = recoverText(original);
		const rendered = renderTextToSvg(looksLikeHtml(recovered) ? stripHtml(recovered) : recovered);

		const before = original.match(/height="(\d+)"/)?.[1] ?? '?';
		const after = rendered.match(/height="(\d+)"/)?.[1] ?? '?';
		console.log(
			`RENDER   ${path} — ${recovered.split('\n').length} lines, ` +
				`${before}px → ${after}px${looksLikeHtml(recovered) ? ', HTML stripped' : ''}`
		);

		if (apply) {
			const { error: uploadError } = await admin.storage
				.from(BUCKET)
				.upload(path, new Blob([rendered], { type: 'image/svg+xml' }), {
					contentType: 'image/svg+xml',
					upsert: true
				});
			if (uploadError) {
				console.error(`FAIL     ${path} — upload: ${uploadError.message}`);
				failed += 1;
				continue;
			}
		}
		rerendered += 1;
	}

	console.log(
		`\n${apply ? 'Re-rendered' : 'Would re-render'}: ${rerendered}` +
			`   already current: ${skipped}   failed: ${failed}`
	);
	if (!apply && rerendered > 0) console.log('Re-run with --apply to write.');
	if (failed > 0) process.exitCode = 1;
}

main().catch((e) => {
	console.error(e instanceof Error ? e.message : e);
	process.exitCode = 1;
});

