  "Total                       $16.66",
  "",
  "",
  "",
  "Paid with Visa ending 4242 on 2026-08-01."
].join("\n");
const svg = renderTextToSvg(body);
writeFileSync("/tmp/yfl-sample-receipt.svg", svg);
console.log("columns:", WRAP_COLUMNS);
console.log("svg:", svg.match(/width="\d+" height="\d+"/)?.[0]);
console.log("lines:", (svg.match(/<tspan/g) ?? []).length);
console.log("old renderer would have been: 800px wide, " + (body.split("\n").length * 20 + 40) + "px tall, URL clipped at ~90 chars");
